<template><div class="boost-overview"><div class="overview-header"><div><span class="eyebrow">PLATFORM OPERATIONS</span><h1>玩家交易概览</h1><p>处理待办，掌握道具发布、认证与交付。</p></div><el-button @click="load" :loading="loading">刷新数据</el-button></div><el-alert v-if="stats.paymentsEnabled===false" title="支付及资金操作暂未开放；可处理用户、认证、发布和查看记录" type="info" :closable="false" show-icon /><el-alert v-if="stats.simulatedPayment" title="本地测试环境：支付、钱包和提现均不涉及真实资金" type="warning" :closable="false" show-icon /><el-alert v-if="error" :title="error" type="error" show-icon /><div class="operations-nav"><el-button v-for="entry in operations.filter(e=>checkPermi([e.permission]))" :key="entry.path" @click="router.push(entry.path)">{{entry.label}}</el-button></div><div class="overview-stats"><div v-for="m in metrics" :key="m.key"><span>{{m.label}}</span><strong>{{m.money?amount(stats[m.key]):stats[m.key]||0}}</strong><small>{{m.hint}}</small></div></div><div class="workbench" v-if="visibleTodos.length"><h2>需要处理</h2><div class="todo-row" v-for="t in visibleTodos" :key="t.path" @click="router.push('/boost/'+t.path)"><div><b>{{t.label}}</b><p>{{t.description}}</p></div><span class="todo-count">{{stats[t.key]||0}}</span><el-icon><ArrowRight /></el-icon></div></div><div class="recent" v-if="canReadOrders"><div class="recent-heading"><h2>最近订单</h2><el-button link @click="router.push('/boost/orders')">查看全部 →</el-button></div><el-table :data="stats.recentOrders||[]" v-loading="loading" empty-text="暂无订单"><el-table-column prop="orderNo" label="订单编号" min-width="210" /><el-table-column prop="title" label="交易内容" min-width="200" /><el-table-column prop="buyerName" label="用户" /><el-table-column prop="workerName" label="卖家" /><el-table-column label="实付款"><template #default="s">{{amount(s.row.amountCents)}}</template></el-table-column><el-table-column label="状态"><template #default="s"><el-tag type="info">{{statusText[s.row.status]}}</el-tag></template></el-table-column></el-table></div></div></template>
<script setup>
import {ref,onMounted,computed} from 'vue';import {useRouter} from 'vue-router';import {ArrowRight} from '@element-plus/icons-vue';import {overview,amount,statusText} from '@/api/boost'
import {checkPermi} from '@/utils/permission'
const visibleTodos=computed(()=>todos.filter(t=>checkPermi(['boost:'+t.path+':read']))),canReadOrders=computed(()=>checkPermi(['boost:orders:read']));
const operations=[{label:'首页文案与大图',path:'/boost/content',permission:'boost:content:read'},{label:'发布图文活动',path:'/boost/activities',permission:'boost:content:read'},{label:'积分商品与转盘',path:'/boost/rewards',permission:'boost:rewards:read'},{label:'玩家管理',path:'/boost/members',permission:'boost:members:read'},{label:'道具发布审核',path:'/boost/listings',permission:'boost:listings:read'}];
const router=useRouter(),stats=ref({}),loading=ref(false),error=ref('');const metrics=[{key:'members',label:'平台用户',hint:'注册用户总数'},{key:'orders',label:'累计订单',hint:'全部交易及历史订单'},{key:'activeOrders',label:'待交付及处理中',hint:'道具交付及历史服务'},{key:'gmvCents',label:'已完成交易额',hint:'按实际支付金额统计',money:true}],todos=[{key:'pendingListings',label:'发布审核',description:'核对道具介绍、详情图片、单价与数量',path:'listings'},{key:'pendingCertifications',label:'店铺认证',description:'查看店铺介绍与游戏资料证明',path:'shops'},{key:'pendingAftersales',label:'售后申请',description:'根据订单记录与凭证处理争议',path:'aftersales'},{key:'pendingWithdrawals',label:'提现申请',description:'核对可提现余额与收款信息',path:'withdrawals'}];async function load(){loading.value=true;error.value='';try{stats.value=(await overview()).data}catch(e){error.value=e.message||'数据加载失败'}finally{loading.value=false}}onMounted(load)
</script>
<style scoped>.operations-nav{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0}.operations-nav .el-button{margin:0}.boost-overview{padding:30px 32px;max-width:1500px;margin:auto;color:#25262b}.overview-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}.eyebrow{font-size:10px;letter-spacing:2px;color:#95979e}.overview-header h1{font-size:28px;margin:10px 0}.overview-header p{font-size:13px;color:#8b8d95}.overview-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:30px;margin:30px 0;padding:24px 0;border-bottom:1px solid #ebecf0}.overview-stats>div{display:flex;flex-direction:column;gap:12px}.overview-stats span{font-size:13px;color:#70727c}.overview-stats strong{font-size:32px;font-weight:650;letter-spacing:-1px}.overview-stats small{font-size:11px;color:#9698a0}.workbench{background:#fff;border:1px solid #eee;border-radius:14px;padding:20px 24px}.workbench h2,.recent h2{font-size:17px;margin:0 0 12px}.todo-row{display:flex;align-items:center;border-top:1px solid #f0f0f2;padding:16px 0;cursor:pointer}.todo-row:hover{background:#fffdf2}.todo-row>div{flex:1}.todo-row b{font-size:14px}.todo-row p{font-size:12px;color:#93959e;margin:6px 0 0}.todo-count{background:#fff3a1;border-radius:7px;padding:4px 12px;margin-right:22px;font-weight:700}.recent{margin-top:28px;background:#fff;border-radius:14px;border:1px solid #eee;padding:24px}.recent-heading{display:flex;justify-content:space-between;align-items:center}@media(max-width:850px){.boost-overview{padding:20px}.overview-stats{grid-template-columns:1fr 1fr}}</style>
